from collections import deque
from decimal import Decimal, getcontext, ROUND_FLOOR

def solve(n, l, d, p):
    getcontext().prec = 60
    pos = [0] * (n + 2)
    for i in range(1, n + 2):
        pos[i] = pos[i - 1] + d[i - 1]
    dp = [Decimal(0)] * (n + 2)
    dp[0] = Decimal(1)
    dq = deque([0])
    for i in range(1, n + 2):
        while dq and pos[i] - pos[dq[0]] > l:
            dq.popleft()
        if not dq:
            break
        f = Decimal(p[i - 1]) / 100 if i <= n else Decimal(1)
        dp[i] = dp[dq[0]] * f
        while dq and dp[dq[-1]] <= dp[i]:
            dq.pop()
        dq.append(i)
    return dp[n + 1] * 1000000

def safe(n, l, d, p):
    y = solve(n, l, d, p)
    fr = y - y.to_integral_value(rounding=ROUND_FLOOR)
    return abs(fr - Decimal('0.5')) > Decimal('0.001')

def gen(rng):
    def fmt(l, d, p):
        return f'{len(p)} {l}\n' + ' '.join(map(str, d)) + '\n' + ' '.join(map(str, p))
    def make(n, l, dlo, dhi, plo, phi):
        while True:
            d = [rng.randint(dlo, dhi) for _ in range(n + 1)]
            p = [rng.randint(plo, phi) for _ in range(n)]
            if safe(n, l, d, p):
                return fmt(l, d, p)
    tests = [fmt(1, [1, 1], [100]), fmt(5, [2, 3], [50]), fmt(1, [3, 1], [50]), fmt(10**9, [10**4, 10**4], [37]),
             fmt(4, [2, 2, 2], [60, 100]), fmt(3, [2, 2, 2], [0, 100])]
    for n in (2, 3, 4, 6, 8, 10, 14):
        for _ in range(3):
            dhi = rng.choice([2, 4, 9])
            l = rng.randint(dhi, 3 * dhi + 2)
            tests.append(make(n, l, 1, dhi, rng.choice([0, 30, 70]), 100))
    tests.append(make(60, 12, 1, 5, 50, 100))
    tests.append(make(100000, 3000, 1, 3, 0, 99))
    tests.append(make(100000, 30000, 1, 10, 1, 99))
    tests.append(make(100000, 100001, 1, 1, 0, 99))
    tests.append(make(100000, 40, 1, 4, 90, 100))
    return tests
